{
  "edits": [
    {
      "hint": 1,
      "original": "'Coal Emperor': Anil Sharma signs Sunny Deol for slapstick comedy",
      "corrected": "'Coal King': Anil Sharma plans an action-drama with Sunny Deol"
    },
    {
      "hint": 2,
      "original": "who made headlines with their 2022 film Gadar 2",
      "corrected": "who created history with their 2023 blockbuster Gadar 2"
    },
    {
      "hint": 3,
      "original": "are reportedly reuniting for a spin-off titled Coal Emperor",
      "corrected": "are reportedly in talks for a new project titled Coal King"
    },
    {
      "hint": 4,
      "original": "According to Bollywood Hungama, the duo discussed a light-hearted comedy set in the world of coal smuggling.",
      "corrected": "According to Pinkvilla, the duo discussed a larger-than-life action-drama set against the backdrop of the coal mafia."
    },
    {
      "hint": 5,
      "original": "have been sketching several concepts over the last five months - and the one which has excited both of them is a modest family drama set around a diamond-smuggling ring.",
      "corrected": "have been discussing several original ideas over the last 2 years - and the one which has excited both of them at this point of time is a larger-than-life drama set against the backdrop of the coal mafia."
    },
    {
      "hint": 6,
      "original": "The script is still in early draft stages and no dialogues have been written yet,",
      "corrected": "The script is written, and it is all work in progress on the dialogue draft at the moment,"
    },
    {
      "hint": 7,
      "original": "he started shooting for a Netflix original with Sidharth Malhotra and Karan Johar as director, followed by a romantic thriller produced by Yash Raj Films.",
      "corrected": "he will soon start shooting with Siddharth P Malhotra for a Netflix original actioner, followed by a big action thriller produced by Excel Entertainment."
    },
    {
      "hint": 8,
      "original": "He is also portraying Lord Shiva in Ramayana and is expected to rejoin that shoot in early 2024.",
      "corrected": "He is playing the part of Lord Hanuman in Ramayana, and will be rejoining the shoot towards the end of 2025."
    },
    {
      "hint": 9,
      "original": "In the release slate, Border 2 and Lahore: 1947 are scheduled for 2027 worldwide.",
      "corrected": "In the release slate, there’s Border 2 and Lahore: 1947 set for arrival in the coming year."
    },
    {
      "hint": 10,
      "original": "Sharma is reportedly shelving Gadar 3 and has confirmed that the Gadar franchise will be retired rather than expanded into a trilogy.",
      "corrected": "Sharma is also working on Gadar 3 as a big-scale period action film; writers are developing an idea to expand the Gadar franchise into a trilogy."
    },
    {
      "hint": 11,
      "original": "In an interview with Pinkvilla in 2024 he allegedly said writers had scrapped all Gadar ideas.",
      "corrected": "In a previous interview with Pinkvilla, he confirmed that the writers are currently developing an idea to expand the Gadar franchise into a trilogy."
    },
    {
      "hint": 12,
      "original": "The director plans to decide which film to shoot next by March 2025, and both Coal Emperor and Gadar 3 are said to have completed scripts.",
      "corrected": "A call on his immediate next will be taken by the end of this year, but the three scripts are presently being worked upon simultaneously."
    },
    {
      "hint": 13,
      "original": "Industry insiders say Coal Emperor could enter production as early as mid-2023 if financing, secured by Anil Sharma's production house, is finalized.",
      "corrected": "The Anil Sharma film could materialize in 2026 (as reported) and talks are in nascent stages; the script/dialogue drafts are still being worked upon."
    },
    {
      "hint": 14,
      "original": "Box office predictions estimate the film will easily cross Rs 50 crore within its first weekend.",
      "corrected": "No official box office predictions exist; past report noted Gadar 2 earned over Rs 500 crore."
    },
    {
      "hint": 15,
      "original": "Stay tuned to Pinkvilla and Bollywood Hungama for official confirmations and release dates.",
      "corrected": "Stay tuned to Pinkvilla for more updates."
    }
  ]
}
